1	<script lang="ts">
2		import { onMount, untrack } from 'svelte';
3		import { SvelteSet } from 'svelte/reactivity';
4		import { page } from '$app/stores';
5		import { goto } from '$app/navigation';
6		import { resolve } from '$app/paths';
7		import { supabase } from '$lib/supabaseClient';
8		import { getSignedReceiptUrls } from '$lib/utils/signedUrl';
9		import { ReceiptService } from '$lib/services/ReceiptService';
10		import { CategoryService } from '$lib/services/CategoryService';
11		import { ExpenseService } from '$lib/services/ExpenseService';
12		import type { ReceiptRow } from '$lib/models/Receipt';
13		import type { Category } from '$lib/types/Category';
14		import { buildCategoryMap } from '$lib/utils/resolveCategory';
15		import { detectDuplicates } from '$lib/utils/duplicateDetection';
16		import { getDuplicateInfo } from '$lib/utils/duplicateHelpers';
17		import {
18			readDateFilter,
19			matchesDateRange,
20			applyDateFilterParams,
21			clearDateFilterParams
22		} from '$lib/utils/sharedDateFilter';
23		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
24		import { processUploadBatch } from '$lib/utils/batchUpload';
25		import { Datepicker } from 'flowbite-svelte';
26		import {
27			toDate,
28			toISODateString,
29			dateOrRangeToDate,
30			formatDate
31		} from '$lib/utils/dateConversion';
32		import { formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
33		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
34		import FilterPanel from '$lib/components/FilterPanel.svelte';
35		import FilteredEmptyState from '$lib/components/FilteredEmptyState.svelte';
36		import DataTable from '$lib/components/DataTable.svelte';
37		import Notification from '$lib/components/Notification.svelte';
38		import { emptySelection } from '$lib/utils/selectionModel';
39		import {
40			newManualReceiptForm,
41			validateManualReceipt,
42			type ManualReceiptForm,
43			type ManualReceiptField
44		} from '$lib/utils/manualReceipt';
45	
46		const receiptService = new ReceiptService(supabase);
47	
48		let allReceipts: ReceiptRow[] = $state([]);
49		let error: string | null = $state(null);
50		let uploading = $state(false);
51		let manual = $state<ManualReceiptForm>(newManualReceiptForm());
52		let showManualForm = $state(false);
53		// Inline validation error for the manual-create form. `field` targets the
54		// offending input so the message renders next to it; 'form' is a general
55		// submit failure shown above the Create button.
56		let manualError: { field: ManualReceiptField | 'form'; message: string } | null = $state(null);
57		let deleting = new SvelteSet<string>();
58	
59		// #{#rct1b} Receipt edit modal state
60		let editingReceipt: ReceiptRow | null = $state(null);
61		let showEditModal = $state(false);
62		let isSavingReceipt = $state(false);
63		let editModalError: string | null = $state(null);
64	
65		// #{#rmc2a} Category state for ReceiptEditModal
66		let categories: Category[] = $state([]);
67		let familyId: string | null = $state(null);
68		let categoryMap: Record<string, Category | null> = $state({});
69	
70		// #{#blk1b} Selection state management (owned by <DataTable>)
71		let receiptSelection = $state(emptySelection());
72		let isDeleting = $state(false);
73		let successMessage: string | null = $state(null);
74		let errorMessage: string | null = $state(null);
75	
76		// #{#sdf2a} Read date filters from URL query parameters
77		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
78		let urlDateFrom = $derived(urlDateFilter.dateFrom);
79		let urlDateTo = $derived(urlDateFilter.dateTo);
80	
81		// Client-side filters - temporary values for inputs
82		let tempFilterDateFrom = $state(readDateFilter($page.url.searchParams).dateFrom);
83		let tempFilterDateTo = $state(readDateFilter($page.url.searchParams).dateTo);
84		let tempFilterMerchant = $state('');
85		let tempFilterAmountMin = $state('');
86		let tempFilterAmountMax = $state('');
87	
88		// Sync temp date values when URL changes
89		$effect(() => {
90			tempFilterDateFrom = urlDateFrom;
91			tempFilterDateTo = urlDateTo;
92		});
93	
94		// Active filter values used for filtering (non-date filters only)
95		let filterMerchant = $state('');
96		let filterAmountMin = $state('');
97		let filterAmountMax = $state('');
98	
99		// #{#dtv3a} Needs Review filter state
100		let filterNeedsReview = $state(false);
101	
102		// #{#dup5a} Duplicate receipts filter state
103		let filterDuplicates = $state(false);
104	
105		async function deleteReceipt(r: ReceiptRow): Promise<void> {
106			if (!confirm('Delete this receipt? This will remove the record and the stored file.')) return;
107			deleting.add(r.id);
108			error = null;
109			try {
110				await receiptService.delete(r.id, r.receipt_image_path);
111				allReceipts = allReceipts.filter((x) => x.id !== r.id);
112			} catch (e: unknown) {
113				error = e instanceof Error ? e.message : 'Failed to delete receipt';
114			} finally {
115				deleting.delete(r.id);
116			}
117		}
118	
119		async function load(): Promise<void> {
120			error = null;
121			try {
122				// DataTable sorts client-side over the full in-memory list; load in a stable order.
123				allReceipts = await receiptService.list('transaction_date', 'desc');
124			} catch (e: unknown) {
125				error = e instanceof Error ? e.message : 'Failed to load receipts';
126			}
127		}
128	
129		onMount(async () => {
130			await load();
131			await loadCategories();
132		});
133	
134		async function onFilesChanged(e: Event): Promise<void> {
135			const input = e.target as HTMLInputElement;
136			const files = input.files;
137			if (!files) return;
138			uploading = true;
139			error = null;
140	
141			// Upload receipts — suspicious dates are silently flagged, no dialog shown.
142			// Each file is processed independently so one failure doesn't abort the batch.
143			const { errorMessage } = await processUploadBatch(
144				files,
145				(file) => receiptService.uploadAndCreate(file),
146				{
147					onSuccess: (receipt) => {
148						allReceipts = [receipt, ...allReceipts];
149					},
150					onError: (file, err) => console.error('Failed to upload receipt', file.name, err)
151				}
152			);
153			error = errorMessage;
154			uploading = false;
155	
156			input.value = '';
157		}
158	
159		// #{#sec1a} Signed URL cache for receipt images
160		let signedUrls: Record<string, string> = $state({});
161	
162		// #{#sec1a} Load signed URLs whenever allReceipts changes
163		// Uses untrack to read signedUrls without creating a reactive loop
164		$effect(() => {
165			const paths = allReceipts.map((r) => r.receipt_image_path).filter((p): p is string => !!p);
166			untrack(() => loadSignedUrls(paths));
167		});
168	
169		async function loadSignedUrls(paths: string[]) {
170			const cached = signedUrls;
171			const newUrls: Record<string, string> = {};
172			const missing: string[] = [];
173			for (const path of paths) {
174				if (cached[path]) newUrls[path] = cached[path];
175				else missing.push(path);
176			}
177			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
178			if (missing.length > 0) {
179				Object.assign(newUrls, await getSignedReceiptUrls(missing));
180			}
181			signedUrls = newUrls;
182		}
183	
184		function getImageUrl(path: string | null): string | null {
185			if (!path) return null;
186			return signedUrls[path] ?? null;
187		}
188	
189		// #{#rct1a} Open edit modal when row is clicked
190		function openEditModal(receipt: ReceiptRow) {
191			editingReceipt = { ...receipt };
192			showEditModal = true;
193			editModalError = null;
194		}
195	
196		// #{#rct4b} Close edit modal
197		function closeEditModal() {
198			showEditModal = false;
199			editingReceipt = null;
200			editModalError = null;
201			isSavingReceipt = false;
202		}
203	
204		// #{#rct5a} Save receipt changes from modal
205		async function handleSaveReceipt(updatedReceipt: ReceiptRow) {
206			isSavingReceipt = true;
207			editModalError = null;
208	
209			try {
210				const patch = {
211					merchant_name: updatedReceipt.merchant_name,
212					total_amount: updatedReceipt.total_amount,
213					transaction_date: updatedReceipt.transaction_date,
214					tax: updatedReceipt.tax,
215					currency: updatedReceipt.currency,
216					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
217					credit_card_name: updatedReceipt.credit_card_name,
218					credit_card_last_4: updatedReceipt.credit_card_last_4,
219					// #{#dtv2d} Preserve confirmed suspicious_date status
220					suspicious_date: updatedReceipt.suspicious_date
221				};
222	
223				const saved = await receiptService.update(updatedReceipt.id, patch);
224				allReceipts = allReceipts.map((r) => (r.id === saved.id ? saved : r));
225	
226				// #{#rct5b} Show success message
227				successMessage = 'Receipt updated successfully';
228				setTimeout(() => {
229					successMessage = null;
230				}, 3000);
231	
232				closeEditModal();
233			} catch (e: unknown) {
234				editModalError = e instanceof Error ? e.message : 'Failed to save receipt';
235			} finally {
236				isSavingReceipt = false;
237			}
238		}
239	
240		// #{#rmc2a} Load family categories for CategoryDropdown in edit modal
241		async function loadCategories() {
242			try {
243				familyId = await getDefaultFamilyId();
244				if (!familyId) return;
245	
246				const categoryService = new CategoryService(supabase);
247				categories = await categoryService.getFamilyCategories(familyId);
248	
249				// Load category assignments for all receipts (RF-09: shared resolver)
250				const expenseService = new ExpenseService(supabase);
251				const user = (await supabase.auth.getUser()).data.user;
252				if (user) {
253					const expenses = await expenseService.getExpenses(user.id);
254					categoryMap = buildCategoryMap(expenses, categories);
255				}
256			} catch (err) {
257				console.error('Error loading categories:', err);
258			}
259		}
260	
261		// #{#rmc2a} Handle category change from ReceiptEditModal
262		async function handleCategoryChange(receiptId: string, category: Category) {
263			if (!familyId) return;
264	
265			try {
266				const expenseService = new ExpenseService(supabase);
267				await expenseService.assignCategory(receiptId, category.id, 'manual');
268	
269				// Create vendor rule if none exists
270				const receipt = allReceipts.find((r) => r.id === receiptId);
271				if (receipt?.merchant_name) {
272					const existingRule = await expenseService.getVendorRule(familyId, receipt.merchant_name);
273					if (!existingRule) {
274						await expenseService.createVendorRule(familyId, receipt.merchant_name, category.id);
275					}
276				}
277	
278				// Update local category map
279				categoryMap = { ...categoryMap, [receiptId]: category };
280			} catch (err) {
281				console.error('Error assigning category:', err);
282			}
283		}
284	
285		async function createManual(e: Event): Promise<void> {
286			e.preventDefault();
287	
288			manualError = null;
289	
290			const validation = validateManualReceipt(manual);
291			if (!validation.ok) {
292				manualError = { field: validation.field, message: validation.message };
293				return;
294			}
295	
296			try {
297				const created = await receiptService.createManual(validation.value);
298				allReceipts = [created, ...allReceipts];
299				// Reset for the next entry — date defaults back to today; form stays expanded.
300				manual = newManualReceiptForm();
301				successMessage = `Receipt created: ${validation.value.merchant_name}`;
302				setTimeout(() => {
303					successMessage = null;
304				}, 3000);
305			} catch (err: unknown) {
306				manualError = {
307					field: 'form',
308					message: err instanceof Error ? err.message : 'Failed to create receipt'
309				};
310			}
311		}
312	
313		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
314			// #{#dup5a} Pre-compute duplicate IDs when filter is active
315			let dupeIds: Set<string> | null = null;
316			if (filterDuplicates) {
317				const dupes = detectDuplicates(rcts);
318				// eslint-disable-next-line svelte/prefer-svelte-reactivity -- local, non-reactive lookup set built and read within this call; SvelteSet would be inappropriate here
319				dupeIds = new Set<string>();
320				for (const ids of dupes.values()) {
321					for (const id of ids) dupeIds.add(id);
322				}
323			}
324	
325			return rcts.filter((r) => {
326				// #{#dtv3a} Filter by suspicious_date (Needs Review)
327				if (filterNeedsReview && !r.suspicious_date) return false;
328	
329				// #{#dup5a} Filter by duplicate status
330				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
331	
332				// #{#sdf1b} Filter by date range using URL parameters
333				if (!matchesDateRange(r.transaction_date, urlDateFrom, urlDateTo)) return false;
334	
335				// Filter by merchant name (local state)
336				if (filterMerchant) {
337					const merchantSearch = filterMerchant.toLowerCase();
338					const merchant = (r.merchant_name || '').toLowerCase();
339					if (!merchant.includes(merchantSearch)) return false;
340				}
341	
342				// Filter by amount range (local state)
343				if (filterAmountMin && r.total_amount !== null) {
344					const minAmount = parseFloat(filterAmountMin);
345					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
346				}
347				if (filterAmountMax && r.total_amount !== null) {
348					const maxAmount = parseFloat(filterAmountMax);
349					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
350				}
351	
352				return true;
353			});
354		}
355	
356		function applyFilterValues(): void {
357			// #{#sdf2a} Update URL with date filters
358			const params = applyDateFilterParams(
359				$page.url.searchParams,
360				tempFilterDateFrom,
361				tempFilterDateTo
362			);
363			goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });
364	
365			// Apply non-date filters locally
366			filterMerchant = tempFilterMerchant;
367			filterAmountMin = tempFilterAmountMin;
368			filterAmountMax = tempFilterAmountMax;
369		}
370	
371		function clearClientFilters(): void {
372			// #{#sdf2a} Clear URL date filters
373			const params = clearDateFilterParams($page.url.searchParams);
374			goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });
375	
376			// Clear local filters
377			tempFilterMerchant = '';
378			tempFilterAmountMin = '';
379			tempFilterAmountMax = '';
380			filterMerchant = '';
381			filterAmountMin = '';
382			filterAmountMax = '';
383	
384			// #{#dtv3a} Clear Needs Review filter
385			filterNeedsReview = false;
386	
387			// #{#dup5a} Clear Duplicates filter
388			filterDuplicates = false;
389		}
390	
391		// applyClientFilters reads every filter variable (URL date range + local filters),
392		// so $derived tracks them all — no explicit dependency list needed.
393		let receipts = $derived(applyClientFilters(allReceipts));
394	
395		// #{#dup1b} #{#dup2b} Detect duplicates on filtered receipts
396		let duplicateGroups = $derived(detectDuplicates(receipts));
397	
398		// #{#dup5a} Detect duplicates on ALL receipts for badge count
399		let allDuplicateGroups = $derived(detectDuplicates(allReceipts));
400		let duplicateReceiptCount = $derived(
401			Array.from(allDuplicateGroups.values()).reduce((sum, ids) => sum + ids.length, 0)
402		);
403	
404		let hasActiveFilters = $derived(
405			urlDateFrom ||
406				urlDateTo ||
407				filterMerchant ||
408				filterAmountMin ||
409				filterAmountMax ||
410				filterNeedsReview ||
411				filterDuplicates
412		);
413	
414		// #{#blk4b} Clear selection
415		function clearSelection(): void {
416			receiptSelection = emptySelection();
417		}
418	
419		// #{#blk2a} #{#blk2b} #{#blk3a} #{#blk3b} Selection-based bulk delete
420		// (native confirm + optimistic update with rollback).
421		async function deleteSelected(): Promise<void> {
422			const idsToDelete = Array.from(receiptSelection.selected);
423			if (idsToDelete.length === 0) return;
424			if (
425				!confirm(
426					`Delete ${idsToDelete.length} selected receipt${idsToDelete.length === 1 ? '' : 's'}? This removes the record and the stored file.`
427				)
428			) {
429				return;
430			}
431	
432			isDeleting = true;
433			errorMessage = null;
434			successMessage = null;
435	
436			// #{#blk3b} Optimistic UI update
437			const originalReceipts = [...allReceipts];
438			allReceipts = allReceipts.filter((r) => !receiptSelection.selected.has(r.id));
439	
440			try {
441				// #{#blk3a} Call bulk delete service
442				await receiptService.bulkDeleteReceipts(idsToDelete);
443	
444				// #{#blk6b} Success feedback
445				successMessage = `Successfully deleted ${idsToDelete.length} receipt${idsToDelete.length === 1 ? '' : 's'}`;
446				clearSelection();
447				setTimeout(() => {
448					successMessage = null;
449				}, 4000);
450			} catch (e: unknown) {
451				// #{#blk3b} Rollback on failure
452				allReceipts = originalReceipts;
453				errorMessage =
454					e instanceof Error ? e.message : 'Failed to delete receipts. Please try again.';
455				setTimeout(() => {
456					errorMessage = null;
457				}, 8000);
458			} finally {
459				isDeleting = false;
460			}
461		}
462	
463		// #{#blk1b} Clear invalid selections when receipts are deleted individually
464		$effect(() => {
465			const validIds = new Set(allReceipts.map((r) => r.id));
466			const filtered = new Set(
467				Array.from(receiptSelection.selected).filter((id) => validIds.has(id))
468			);
469			if (filtered.size !== receiptSelection.selected.size) {
470				receiptSelection = { selected: filtered, anchorId: receiptSelection.anchorId };
471			}
472		});
473	</script>
474	
475	<svelte:head>
476		<title>Receipts</title>
477	</svelte:head>
478	
479	<div class="mb-6 flex items-start justify-between gap-4">
480		<div>
481			<h1 class="mb-2 text-2xl font-bold">Receipts</h1>
482			<p class="text-gray-600">Upload and manage your receipts.</p>
483		</div>
484		<label
485			class="inline-flex cursor-pointer items-center gap-2 rounded border bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700"
486		>
487			<input
488				class="hidden"
489				type="file"
490				multiple
491				onchange={onFilesChanged}
492				accept="image/jpeg,image/png,image/heic,application/pdf"
493			/>
494			{uploading ? 'Uploading…' : 'Upload receipts'}
495		</label>
496	</div>
497	
498	<!-- #{#blk6b} Success/Error notifications -->
499	{#if error}
500		<Notification type="error" message={error} onDismiss={() => (error = null)} />
501	{/if}
502	
503	{#if errorMessage}
504		<Notification type="error" message={errorMessage} onDismiss={() => (errorMessage = null)} />
505	{/if}
506	
507	{#if successMessage}
508		<Notification type="success" message={successMessage} onDismiss={() => (successMessage = null)} />
509	{/if}
510	
511	<!-- Filters -->
512	<FilterPanel
513		bind:dateFrom={tempFilterDateFrom}
514		bind:dateTo={tempFilterDateTo}
515		onApply={applyFilterValues}
516		onClear={clearClientFilters}
517		gridClass="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5"
518	>
519		{#snippet filters()}
520			<div>
521				<label for="rcpt-filter-merchant" class="mb-1 block text-sm font-medium">Merchant Name</label>
522				<input
523					id="rcpt-filter-merchant"
524					type="text"
525					bind:value={tempFilterMerchant}
526					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
527					placeholder="Search merchant..."
528				/>
529			</div>
530			<div>
531				<label for="rcpt-filter-amount-min" class="mb-1 block text-sm font-medium"
532					>Min Amount ($)</label
533				>
534				<input
535					id="rcpt-filter-amount-min"
536					type="number"
537					step="0.01"
538					bind:value={tempFilterAmountMin}
539					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
540					placeholder="Min"
541				/>
542			</div>
543			<div>
544				<label for="rcpt-filter-amount-max" class="mb-1 block text-sm font-medium"
545					>Max Amount ($)</label
546				>
547				<input
548					id="rcpt-filter-amount-max"
549					type="number"
550					step="0.01"
551					bind:value={tempFilterAmountMax}
552					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
553					placeholder="Max"
554				/>
555			</div>
556		{/snippet}
557		{#snippet secondary()}
558			<!-- #{#dtv3a} Needs Review filter toggle -->
559			<div class="mt-3">
560				<label class="inline-flex cursor-pointer items-center gap-2">
561					<input
562						type="checkbox"
563						bind:checked={filterNeedsReview}
564						class="h-4 w-4 rounded border-gray-300"
565						aria-label="Show only receipts needing date review"
566					/>
567					<span class="text-sm font-medium">
568						Show only receipts needing date review
569						{#if filterNeedsReview || allReceipts.some((r) => r.suspicious_date)}
570							<span
571								class="ml-2 inline-flex items-center gap-1 rounded-full bg-orange-100 px-2 py-0.5 text-xs font-semibold text-orange-800"
572								role="status"
573								aria-live="polite"
574							>
575								<svg
576									class="h-3 w-3"
577									fill="none"
578									stroke="currentColor"
579									viewBox="0 0 24 24"
580									aria-hidden="true"
581								>
582									<path
583										stroke-linecap="round"
584										stroke-linejoin="round"
585										stroke-width="2"
586										d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
587									/>
588								</svg>
589								{allReceipts.filter((r) => r.suspicious_date).length}
590							</span>
591						{/if}
592					</span>
593				</label>
594			</div>
595			<!-- #{#dup5a} Duplicate receipts filter -->
596			<div class="mt-3">
597				<label class="inline-flex cursor-pointer items-center gap-2">
598					<input
599						type="checkbox"
