22	export interface ManualReceiptValues {
23		merchant_name: string;
24		total_amount: number;
25		transaction_date: string;
26	}
27	
28	export type ManualReceiptField = 'merchant_name' | 'total_amount';
29	
30	export type ManualReceiptValidation =
31		| { ok: true; value: ManualReceiptValues }
32		| { ok: false; field: ManualReceiptField; message: string };
33	
34	export function validateManualReceipt(form: ManualReceiptForm): ManualReceiptValidation {
35		const merchant_name = form.merchant_name.trim();
36		if (merchant_name === '') {
37			return { ok: false, field: 'merchant_name', message: 'Enter a merchant name.' };
38		}
39	
40		const total_amount = parseFloat(form.total_amount);
41		if (Number.isNaN(total_amount) || total_amount <= 0) {
42			return { ok: false, field: 'total_amount', message: 'Receipt amount should greater than 0.00' };
43		}
44	
45		return {
46			ok: true,
47			value: {
48				merchant_name,
49				total_amount,
50				transaction_date: form.transaction_date
51			}
52		};
53	}
